export const importDocumentSettingsInput=z.object({documentId:z.string().cuid(),classification:z.nativeEnum(ClientImportClassification),classificationDescription:z.string().trim().max(200).optional().nullable(),disposition:z.nativeEnum(ClientImportDocumentDisposition),completedAt:reviewedDate.optional().nullable(),signatureReviewStatus:z.nativeEnum(ImportedSignatureReviewStatus).default("NOT_APPLICABLE"),validityReviewStatus:z.nativeEnum(ImportedValidityReviewStatus).default("UNREVIEWED"),expirationDate:reviewedDate.optional().nullable()}).superRefine((value,context)=>{
  if(value.classification==="OTHER"&&!value.classificationDescription)context.addIssue({code:"custom",path:["classificationDescription"],message:"Describe this Other document"});
  if(value.completedAt&&value.completedAt>new Date())context.addIssue({code:"custom",path:["completedAt"],message:"Completion date cannot be in the future"});
  if(value.disposition==="HISTORICAL_COMPLETE"&&!["CONFIRMED_EXTERNAL","NOT_APPLICABLE"].includes(value.signatureReviewStatus))context.addIssue({code:"custom",path:["signatureReviewStatus"],message:"Historical completion requires confirmed external signature evidence or an authorized not-applicable decision"});
  if(value.validityReviewStatus==="CONFIRMED"&&!value.expirationDate)context.addIssue({code:"custom",path:["expirationDate"],message:"A confirmed expiration date is required"});
});
